    # Use O(min(n,m)) space DP for edit distance
    # Ensure b is the shorter string to minimize space
    if len(b) > len(a):
        a, b = b, a
    n, m = len(a), len(b)
    # previous row
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        ai = a[i - 1]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                cost = 0
            else:
                cost = 1
            # deletion (prev[j] + 1), insertion (cur[j-1] + 1), substitution (prev[j-1] + cost)
            cur[j] = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
        prev = cur
