def solve(nums):
    """Return the length of the longest strictly increasing subsequence using O(n^2) DP.
    Works for all integer inputs; acceptable for typical test sizes.
    """
    if not nums:
        return 0
    n = len(nums)
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)

