    """Compute Levenshtein distance between two strings.
    Uses DP with O(m*n) time and O(min(m,n)) space.
    """
    m, n = len(word1), len(word2)
    # Ensure word2 is the shorter string for space efficiency
    if n > m:
        word1, word2 = word2, word1
        m, n = n, m
    prev = list(range(n + 1))
    for i in range(1, m + 1):
        cur = [i] + [0] * n
        for j in range(1, n + 1):
